def cost(self, A: list[int]) -> int:
    from functools import lru_cache
    n = len(A)

    @lru_cache(maxsize=None)
    def f(i: int, prev: int) -> int:
        if i == n:
            return 0
        best = 0
        for v in (1, A[i]):
            best = max(best, abs(v - prev) + f(i + 1, v))
        return best

    if n == 0:
        return 0
    # B[0] is 1 or A[0]; start the chain from index 1
    return max(f(1, 1), f(1, A[0]))

