public long cost(int[] A) {
    int n = A.length;
    if (n <= 1) return 0;
    long high = 0, low = 0;
    for (int i = 1; i < n; i++) {
        long nh = Math.max(high + Math.abs((long) A[i] - A[i - 1]),
                           low  + Math.abs((long) A[i] - 1));
        long nl = Math.max(high + Math.abs(1L - A[i - 1]),
                           low  + 0);
        high = nh;
        low = nl;
    }
    return Math.max(high, low);
}

