def cost(self, A: list[int]) -> int:
    n = len(A)
    if n <= 1:
        return 0
    high = low = 0
    for i in range(1, n):
        nh = max(high + abs(A[i] - A[i - 1]), low + abs(A[i] - 1))
        nl = max(high + abs(1 - A[i - 1]), low + 0)
        high, low = nh, nl
    return max(high, low)
